def apply(path, pairs):
    text = open(path, encoding="utf-8").read()
    failures = []
    for old, new in pairs:
        n = text.count(old)
        if n != 1:
            failures.append((n, old[:70]))
            continue
        text = text.replace(old, new)
    if failures:
        print(f"!! {path}: {len(failures)} pattern(s) did not match exactly once; file unchanged")
        for n, o in failures:
            print(f"   count={n} :: {o!r}")
        return False
    open(path, "w", encoding="utf-8").write(text)
    print(f"OK {path}: {len(pairs)} replacements applied")
    return True


